package vn.nanase.hako;

import android.app.*;
import vn.nanase.sharedsync.RelayClient;
import android.content.*;
import android.os.*;
import android.text.Html;
import android.util.AtomicFile;
import android.widget.*;
import org.json.*;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Element;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import javax.net.ssl.HttpsURLConnection;

/** Optional shared progress. Failure never blocks local reading or starts Gecko. */
public final class ServerBridge {
    static final ScheduledThreadPoolExecutor worker=new ScheduledThreadPoolExecutor(1);
    static final ThreadLocal<Boolean> applying=new ThreadLocal<>();
    static final Object gate=new Object();static ScheduledFuture<?> scheduled;
    static volatile String activeBook="";
    static final java.util.concurrent.atomic.AtomicBoolean queued=new java.util.concurrent.atomic.AtomicBoolean();
    static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("server_bridge",0);}
    static boolean enabled(Context c){return !prefs(c).getString("token","").isEmpty();}
    static boolean importing(){return Boolean.TRUE.equals(applying.get());}
    static void status(Context c,String text){prefs(c).edit().putString("status",text).apply();}
    public static void localPosition(Context context,String book,String chapter,int paragraph,float fraction){
        if(importing()||!enabled(context)||book.equals("demo"))return;
        Context c=context.getApplicationContext();synchronized(gate){try{android.content.SharedPreferences p=prefs(c);long seq=p.getLong("sequence",0)+1;JSONObject pending=new JSONObject().put("position_policy","latest").put("book",book).put("chapter",chapter).put("paragraph",paragraph).put("fraction",fraction).put("sequence",seq).put("event_id",UUID.randomUUID().toString()).put("relay_base_revision",new RelayClient(c).revision(book)).put("base_revision",p.getLong("revision:"+book,0)).put("session",p.getString("session:"+book,""));if(pending.optString("session").isEmpty()){pending.put("session",UUID.randomUUID().toString());}p.edit().putLong("sequence",seq).putString("session:"+book,pending.getString("session")).putString("pending:"+book,pending.toString()).remove("cloud_pending:"+book).commit();}catch(Exception ignored){}if(scheduled!=null)scheduled.cancel(false);scheduled=worker.schedule(()->sync(c),1800,TimeUnit.MILLISECONDS);}
    }
    public static void completed(Context c,String book){if(importing()||!enabled(c))return;Store.Book b=Store.get(c).book(book);if(b!=null&&!b.current.isEmpty())localPosition(c,book,b.current,b.pos,b.fraction);}
    public static void flags(Context c,String book){if(importing()||!enabled(c))return;prefs(c).edit().putBoolean("flags:"+book,true).apply();kick(c);}
    public static void kick(Context context){if(!enabled(context))return;Context c=context.getApplicationContext();if(queued.compareAndSet(false,true))worker.execute(()->{queued.set(false);sync(c);});}
    static JSONObject request(Context c,String method,String path,JSONObject value,boolean auth)throws Exception{
        URL url=new URL(prefs(c).getString("server","https://nanains.duckdns.org/hako")+path);if(!url.getProtocol().equals("https")||url.getUserInfo()!=null)throw new IOException("Cần địa chỉ HTTPS");HttpsURLConnection connection=(HttpsURLConnection)url.openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(5000);connection.setReadTimeout(10000);connection.setRequestMethod(method);if(auth)connection.setRequestProperty("Authorization","Bearer "+prefs(c).getString("token",""));
        try{if(value!=null){connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");try(OutputStream out=connection.getOutputStream()){out.write(value.toString().getBytes(StandardCharsets.UTF_8));}}int code=connection.getResponseCode();if(code<200||code>=300)throw new IOException("Đồng bộ đang chờ ("+code+")");try(InputStream in=connection.getInputStream()){ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(data.size()+n>8*1024*1024)throw new IOException("Dữ liệu quá lớn");data.write(buffer,0,n);}return new JSONObject(data.toString("UTF-8"));}}finally{connection.disconnect();}
    }
    static ArrayList<String> paragraphs(Store store,String cid){ArrayList<String> rows=new ArrayList<>();try{File file=new File(store.dir(cid),"content.html");if(file.length()>4*1024*1024)return rows;String html=new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);Element body=Jsoup.parseBodyFragment(html).body();for(Element e:new ArrayList<Element>(body.select("details"))){Element summary=e.selectFirst("summary");if(summary!=null)summary.remove();e.replaceWith(new Element("span").text(" [✎] "));}for(Element e:body.children()){String text=Html.fromHtml(e.outerHtml(),Html.FROM_HTML_MODE_LEGACY).toString().trim();if(!text.isEmpty())rows.add(text);}}catch(Exception ignored){}return rows;}
    static JSONObject locator(Store store,JSONObject pending)throws Exception{int p=pending.optInt("paragraph");float f=(float)pending.optDouble("fraction");ArrayList<String> rows=paragraphs(store,pending.getString("chapter"));String quote="";if(p<rows.size()){String text=rows.get(p);int at=Math.min(text.length(),Math.round(f*text.length()));quote=text.substring(at).replaceAll("\\s+"," ").trim();if(quote.length()>180)quote=quote.substring(0,180);}return new JSONObject().put("paragraph",p).put("fraction",f).put("quote",quote);}
    static void sync(Context c){if(!enabled(c))return;try{
        Store store=Store.get(c);android.content.SharedPreferences p=prefs(c);RelayClient cloud=new RelayClient(c);if(!cloud.ready())try{cloud.configure(request(c,"GET","/v2/relay/config",null,true));}catch(Exception ignored){}boolean cloudPending=false;if(cloud.ready())try{cloudSync(c,cloud);return;}catch(Exception cloudFailure){cloudPending=true;}Map<String,?> snapshot=p.getAll();
        for(String key:snapshot.keySet())if(key.startsWith("pending:")){
            String saved=String.valueOf(snapshot.get(key));JSONObject pending=new JSONObject(saved);String bid=pending.getString("book");Store.Book b=store.book(bid);if(b==null)continue;Store.Chapter selected=store.chapter(bid,pending.getString("chapter"));if(selected==null)continue;
            JSONArray links=new JSONArray();List<Store.Chapter> chapters=store.chapters(bid);for(Store.Chapter ch:chapters)links.put(new JSONObject().put("title",ch.title).put("url",ch.url));JSONArray read=new JSONArray();for(String id:store.readingIds(bid,chapters))read.put(id);
            JSONObject payload=new JSONObject().put("position_policy","latest").put("book",new JSONObject().put("title",b.title).put("url",b.url)).put("chapters",links).put("chapter_url",selected.url).put("locator",locator(store,pending)).put("read",read);for(String field:new String[]{"sequence","event_id","base_revision","session"})payload.put(field,pending.get(field));
            JSONObject result=request(c,"POST","/v2/bridge/push",payload,true);
            synchronized(gate){android.content.SharedPreferences.Editor editor=p.edit();if(saved.equals(p.getString(key,""))){editor.remove(key);if(cloudPending)editor.putString("cloud_pending:"+bid,saved);}if(result.optBoolean("conflict")){editor.putString("conflict:"+bid,pending.toString());JSONObject remote=result.optJSONObject("current");if(remote!=null)editor.putString("remote:"+bid,remote.toString());}else if(result.has("revision"))editor.remove("conflict:"+bid).putLong("revision:"+bid,result.optLong("revision"));editor.commit();}
        }
        for(String key:p.getAll().keySet())if(key.startsWith("flags:")&&p.getBoolean(key,false)){String bid=key.substring(6);Store.Book b=store.book(bid);if(b!=null){request(c,"POST","/v1/books/"+bid+"/flags",new JSONObject().put("favorite",b.pinned).put("completed",store.isCompleted(bid)),true);p.edit().remove(key).apply();}}
        JSONObject library=request(c,"GET","/v1/library",null,true);JSONArray books=library.optJSONArray("books"),positions=library.optJSONArray("positions");HashMap<String,JSONObject> remotePositions=new HashMap<>();for(int n=0;positions!=null&&n<positions.length();n++){JSONObject position=positions.getJSONObject(n);remotePositions.put(position.optString("book"),position);}
        for(int n=0;books!=null&&n<books.length();n++){JSONObject book=books.getJSONObject(n);String bid=book.getString("id");JSONObject shared=library.optJSONObject("shared"),flags=shared==null?null:shared.optJSONObject(bid);if(flags!=null&&!p.getBoolean("flags:"+bid,false)){applying.set(true);try{if(flags.has("favorite"))store.pin(bid,flags.optBoolean("favorite"));if(flags.has("completed"))store.setCompleted(bid,flags.optBoolean("completed"));}finally{applying.remove();}}JSONObject remote=remotePositions.get(bid);Store.Book local=store.book(bid);long revision=remote==null?0:remote.optLong("revision");if(local!=null&&revision<=p.getLong("pulled:"+bid,0)&&book.optString("read_revision").equals(p.getString("readstate:"+bid,"")))continue;JSONObject data=remoteBook(c,bid);apply(c,data);p.edit().putLong("pulled:"+bid,revision).putString("readstate:"+bid,book.optString("read_revision")).apply();}
        status(c,"Đã đồng bộ hai chiều");
    }catch(Exception e){status(c,"Chờ kết nối · Tiến độ vẫn lưu trên máy");}}
    static void apply(Context c,JSONObject data)throws Exception{apply(c,data,false);}
    static void apply(Context c,JSONObject data,boolean force)throws Exception{Store store=Store.get(c);android.content.SharedPreferences p=prefs(c);JSONObject book=data.getJSONObject("book");String bid=book.getString("id");applying.set(true);try{store.putBook(new HakoParser.Link(bid,book.getString("title"),book.getString("url")));JSONArray chapters=data.getJSONArray("chapters");ArrayList<HakoParser.Link> links=new ArrayList<>();for(int i=0;i<chapters.length();i++){JSONObject ch=chapters.getJSONObject(i);links.add(new HakoParser.Link(ch.getString("id"),ch.optString("title"),ch.getString("url")));}if(!links.isEmpty()){store.catalog(bid,links);c.getSharedPreferences("settings",0).edit().putBoolean("catalog_failed_"+bid,true).apply();}JSONArray read=data.optJSONArray("read");for(int i=0;read!=null&&i<read.length();i++)store.readChapter(read.getString(i));JSONObject position=data.optJSONObject("position");if(position==null)return;
            p.edit().putString("remote:"+bid,position.toString()).apply();if(!force&&(activeBook.equals(bid)||p.contains("pending:"+bid)||p.contains("conflict:"+bid)))return;
            String cid=position.optString("legacy_chapter",position.optString("chapter").replaceFirst("-c([0-9]+)$","-$1"));JSONObject loc=position.optJSONObject("portable");int paragraph=loc==null?0:loc.optInt("paragraph");float fraction=loc==null?0:(float)loc.optDouble("fraction");String quote=loc==null?"":loc.optString("quote");ArrayList<String> rows=paragraphs(store,cid);if(quote.length()>=8)for(int i=0;i<rows.size();i++){String text=rows.get(i).replaceAll("\\s+"," ").trim();int at=text.indexOf(quote);if(at>=0){paragraph=i;fraction=at/(float)Math.max(1,text.length());break;}}
            store.position(bid,cid,paragraph,fraction);android.content.SharedPreferences.Editor applied=p.edit().putLong("revision:"+bid,position.optLong("revision"));if(!position.optString("device").equals(p.getString("device","")))applied.remove("cloud_pending:"+bid);applied.apply();
        }finally{applying.remove();}}
    static JSONObject remoteBook(Context c,String bid)throws Exception{RelayClient cloud=new RelayClient(c);if(!cloud.ready())return request(c,"GET","/v2/bridge/books/"+bid,null,true);JSONObject snapshot=cloud.snapshot(activeBook);JSONArray books=snapshot.getJSONArray("books");for(int i=0;i<books.length();i++)if(bid.equals(books.optJSONObject(i).optString("id")))return RelayClient.document(cloud.entry(books.getJSONObject(i)),snapshot.optJSONArray("positions"),snapshot.optJSONObject("read"),true);throw new IOException("Chưa có vị trí dùng chung");}
    static void cloudSync(Context c,RelayClient cloud)throws Exception{Store store=Store.get(c);android.content.SharedPreferences p=prefs(c);android.content.SharedPreferences settings=c.getSharedPreferences("settings",0);for(Store.Book existing:store.books()){if(!p.getBoolean("cloud_seeded:"+existing.id,false)){if(existing.pinned||store.isCompleted(existing.id))p.edit().putBoolean("flags:"+existing.id,true).putBoolean("seed_flags:"+existing.id,true).commit();p.edit().putBoolean("cloud_seeded:"+existing.id,true).commit();}JSONArray marks;try{marks=new JSONArray(settings.getString("marks-"+existing.id,"[]"));}catch(Exception e){continue;}boolean changed=false;for(int n=0;n<marks.length();n++){JSONObject mark=marks.getJSONObject(n);if(mark.optString("id").isEmpty()){mark.put("id",UUID.randomUUID().toString());changed=true;}if(!p.getBoolean("mark_synced:"+mark.getString("id"),false))bookmark(c,existing.id,mark,false,false);}if(changed)settings.edit().putString("marks-"+existing.id,marks.toString()).commit();}for(String key:p.getAll().keySet())if(key.startsWith("pending:")||key.startsWith("cloud_pending:")){String saved=p.getString(key,"{}");JSONObject pending=new JSONObject(saved);String bid=pending.getString("book");Store.Book b=store.book(bid);Store.Chapter current=store.chapter(bid,pending.getString("chapter"));if(b==null||current==null)continue;JSONArray chapters=new JSONArray(),read=new JSONArray();List<Store.Chapter> all=store.chapters(bid);Set<String> known=store.readingIds(bid,all);for(Store.Chapter ch:all){chapters.put(new JSONObject().put("title",ch.title).put("url",ch.url));if(known.contains(ch.id))read.put(RelayClient.chapterId(ch.url));}JSONObject event=new JSONObject().put("book",bid).put("chapter",RelayClient.chapterId(current.url)).put("locator",locator(store,pending)).put("read_ids",read).put("metadata",new JSONObject().put("book",new JSONObject().put("id",bid).put("title",b.title).put("url",b.url)).put("chapters",chapters)).put("relay_base_revision",pending.optLong("relay_base_revision",0));for(String field:new String[]{"sequence","event_id","session"})event.put(field,pending.get(field));JSONObject result=cloud.send(event);synchronized(gate){android.content.SharedPreferences.Editor edit=p.edit();if(saved.equals(p.getString(key,"")))edit.remove(key);if(result.optBoolean("conflict"))edit.putString("conflict:"+bid,pending.toString());else if(result.has("revision"))edit.remove("conflict:"+bid).putLong("revision:"+bid,result.optLong("revision"));edit.commit();}}
        for(String key:p.getAll().keySet())if(key.startsWith("flags:")&&p.getBoolean(key,false)){String bid=key.substring(6);Store.Book b=store.book(bid);if(b!=null){JSONObject values=new JSONObject().put("favorite",b.pinned).put("completed",store.isCompleted(bid));if(p.getBoolean("seed_flags:"+bid,false)){JSONObject remote=cloud.snapshot().optJSONObject("shared");remote=remote==null?null:remote.optJSONObject(bid);if(remote!=null)values.put("favorite",b.pinned||remote.optBoolean("favorite")).put("completed",store.isCompleted(bid)||remote.optBoolean("completed"));}cloud.flags(bid,values);p.edit().remove(key).remove("seed_flags:"+bid).apply();}}
        for(String key:p.getAll().keySet())if(key.startsWith("mark:")){String saved=p.getString(key,"{}");JSONObject item=new JSONObject(saved);cloud.bookmark(item.getString("book"),item.getJSONObject("value"));if(saved.equals(p.getString(key,"")))p.edit().remove(key).putBoolean("mark_synced:"+item.getJSONObject("value").getString("id"),true).apply();}
        JSONObject snapshot=cloud.snapshot(activeBook);JSONArray books=snapshot.optJSONArray("books");for(int i=0;books!=null&&i<books.length();i++){JSONObject entry=books.getJSONObject(i);String bid=entry.getString("id");JSONObject data=RelayClient.document(cloud.entry(entry),snapshot.optJSONArray("positions"),snapshot.optJSONObject("read"),true);JSONObject position=data.optJSONObject("position");String fingerprint=entry.optLong("metadata_revision")+":"+data.optJSONArray("read")+":"+(position==null?0:position.optLong("revision"));if(!fingerprint.equals(p.getString("cloud_pulled:"+bid,""))){apply(c,data);if(!activeBook.equals(bid)&&!p.contains("pending:"+bid)&&!p.contains("conflict:"+bid))p.edit().putString("cloud_pulled:"+bid,fingerprint).apply();}if(position!=null&&!p.contains("pending:"+bid)&&!p.contains("conflict:"+bid))cloud.observed(bid,position.optLong("revision"));JSONObject flags=snapshot.optJSONObject("shared");flags=flags==null?null:flags.optJSONObject(bid);if(flags!=null&&!p.getBoolean("flags:"+bid,false)){applying.set(true);try{store.pin(bid,flags.optBoolean("favorite"));store.setCompleted(bid,flags.optBoolean("completed"));}finally{applying.remove();}}
            JSONArray marks=snapshot.optJSONArray("bookmarks"),selected=new JSONArray();for(int n=0;marks!=null&&n<marks.length();n++){JSONObject m=marks.getJSONObject(n);if(!bid.equals(m.optString("book")))continue;String cid=m.optString("chapter").replaceFirst("-c([0-9]+)$","-$1");JSONObject loc=m.optJSONObject("portable");JSONObject anchor=m.optJSONObject("anchor");int paragraph=loc!=null?loc.optInt("paragraph"):anchor==null?0:anchor.optInt("block");float fraction=loc==null?0:(float)loc.optDouble("fraction");selected.put(new JSONObject().put("id",m.optString("id")).put("chapter",cid).put("pos",paragraph).put("fraction",fraction).put("title",m.optString("label","Đánh dấu")));}c.getSharedPreferences("settings",0).edit().putString("marks-"+bid,selected.toString()).apply();}
        status(c,"Đã đồng bộ qua Cloudflare · Không phụ thuộc server nhà");
    }
    public static void bookmark(Context c,String bid,JSONObject mark,boolean deleted){bookmark(c,bid,mark,deleted,true);}
    static void bookmark(Context c,String bid,JSONObject mark,boolean deleted,boolean schedule){if(!enabled(c))return;try{String id=mark.optString("id");if(id.isEmpty())return;Store store=Store.get(c);Store.Chapter ch=store.chapter(bid,mark.optString("chapter"));if(ch==null)return;JSONObject pending=new JSONObject().put("chapter",ch.id).put("paragraph",mark.optInt("pos")).put("fraction",mark.optDouble("fraction"));JSONObject value=new JSONObject().put("id",id).put("chapter",RelayClient.chapterId(ch.url)).put("label",mark.optString("title")).put("portable",locator(store,pending)).put("deleted",deleted);prefs(c).edit().putString("mark:"+id,new JSONObject().put("book",bid).put("value",value).toString()).commit();if(schedule)kick(c);}catch(Exception ignored){}}
    static void choosePosition(Activity activity){Context c=activity.getApplicationContext();ArrayList<String> books=new ArrayList<>(),labels=new ArrayList<>();Store store=Store.get(c);for(String key:prefs(c).getAll().keySet())if(key.startsWith("remote:")){String bid=key.substring(7);books.add(bid);Store.Book b=store.book(bid);labels.add((prefs(c).contains("conflict:"+bid)?"Cần chọn vị trí · ":"")+(b==null?bid:b.title));}new AlertDialog.Builder(activity).setTitle("Vị trí dùng chung").setItems(labels.toArray(new String[0]),(d,n)->{String bid=books.get(n);new AlertDialog.Builder(activity).setTitle("Tiếp tục từ đâu?").setMessage("Giữ tiến độ của app này hoặc nhận vị trí mới nhất từ hệ thống đồng bộ.").setPositiveButton("Dùng vị trí chung",(x,w)->worker.execute(()->{try{JSONObject data=remoteBook(c,bid);JSONObject position=data.optJSONObject("position");if(position==null)return;Runnable change=()->{try{prefs(c).edit().remove("pending:"+bid).remove("conflict:"+bid).apply();new RelayClient(c).resolve(bid,position.optLong("revision"));apply(c,data,true);}catch(Exception e){status(c,"Chưa nhận được vị trí");}};activity.runOnUiThread(()->{if(activity instanceof MainActivity)((MainActivity)activity).bridgeResume(bid,position.optString("legacy_chapter"),change);});}catch(Exception e){activity.runOnUiThread(()->Toast.makeText(activity,"Chưa kết nối được. Tiến độ trên máy được giữ.",Toast.LENGTH_LONG).show());}})).setNeutralButton("Giữ vị trí app này",(x,w)->worker.execute(()->{try{JSONObject data=remoteBook(c,bid);JSONObject remote=data.optJSONObject("position");new RelayClient(c).resolve(bid,remote==null?0:remote.optLong("revision"));prefs(c).edit().remove("conflict:"+bid).putLong("revision:"+bid,remote==null?0:remote.optLong("revision")).putString("session:"+bid,UUID.randomUUID().toString()).commit();Store.Book b=store.book(bid);if(b!=null)localPosition(c,bid,b.current,b.pos,b.fraction);sync(c);}catch(Exception e){status(c,"Đã giữ vị trí trên máy · Chờ kết nối");}})).setNegativeButton("Để sau",null).show();}).setNegativeButton("Đóng",null).show();}
    public static void settings(Activity activity){Context c=activity.getApplicationContext();LinearLayout box=new LinearLayout(activity);box.setOrientation(1);TextView state=new TextView(activity);state.setPadding(20,16,20,16);state.setText(prefs(c).getString("status","Liên kết để dùng chung tiến độ với Hako Server. Mỗi app vẫn đọc độc lập khi mất kết nối."));box.addView(state);TextView automatic=new TextView(activity);automatic.setText("Tự gửi vị trí khi rời chương. Không cần chọn vị trí giữa hai máy.");automatic.setPadding(20,8,20,12);box.addView(automatic);EditText code=new EditText(activity);code.setHint("Mã 6 số từ /hako");code.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);box.addView(code);AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Đồng bộ Hako Server").setView(box).setPositiveButton("Liên kết",null).setNeutralButton("Đồng bộ ngay",(d,w)->{kick(c);Toast.makeText(activity,"Đang đối chiếu dữ liệu đọc",Toast.LENGTH_SHORT).show();}).setNegativeButton("Đóng",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=code.getText().toString().trim();if(!value.matches("[0-9]{6}")){state.setText("Nhập đủ 6 chữ số");return;}state.setText("Đang chờ duyệt trên /hako…");worker.execute(()->{try{JSONObject ticket=request(c,"POST","/pair/request",new JSONObject().put("code",value).put("name","Hako Pocket · "+Build.MODEL),false);for(int i=0;i<150;i++){Thread.sleep(1800);JSONObject result=request(c,"POST","/pair/poll",ticket,false);if(result.optString("state").equals("rejected"))throw new IOException("Yêu cầu bị từ chối");if(result.optString("state").equals("approved")){prefs(c).edit().putString("token",result.getString("token")).putString("device",result.getString("device")).commit();activity.runOnUiThread(()->state.setText("Đã liên kết. Đang đồng bộ thư viện và vị trí đọc."));for(Store.Book existing:Store.get(c).books())if(existing.current!=null&&!existing.current.isEmpty())localPosition(c,existing.id,existing.current,existing.pos,existing.fraction);sync(c);return;}}throw new IOException("Mã đã hết hạn");}catch(Exception e){activity.runOnUiThread(()->state.setText("Chưa liên kết. Tạo mã mới trên /hako rồi thử lại."));}});}));dialog.show();}
}
